// Googleからの返答（Base64文字列）を取得
const base64String = $input.item.json.audioContent;

// Base64をバイナリデータ（ファイル）に変換
const binaryData = Buffer.from(base64String, 'base64');

// 次のノード（Google Drive）へ渡す形に整える
return {
  binary: {
    data: {
      data: base64String,
      mimeType: 'audio/mpeg',
      fileName: 'voice.mp3' // 仮の名前
    }
  },
  json: $input.item.json // 元のデータも残しておく
};

// 1. 各ノード名の設定
const GENKO_NODE_NAME = "Get row(s) in sheet"; 
const JISHO_NODE_NAME = "Get row(s) in sheet1"; 

// 2. 原稿の取得
let script = "";
try {
  script = $node[GENKO_NODE_NAME].json["音声原稿"] || "";
} catch (e) {
  return { error: `ノード '${GENKO_NODE_NAME}' からデータが見つかりません。` };
}

// 3. 辞書の全取得（.all() を使うことで全行取得を確実にします）
let dictionaryItems = [];
try {
  dictionaryItems = $(JISHO_NODE_NAME).all();
} catch (e) {
  return { error: `辞書ノード '${JISHO_NODE_NAME}' の取得に失敗しました。` };
}

// 4. 置換処理の実行
if (script !== "") {
  // 辞書の各アイテムに対してループ
  for (const item of dictionaryItems) {
    const word = item.json.Word;
    const reading = item.json.Reading;

    if (word && reading && typeof word === 'string') {
      // 特殊文字をエスケープして正規表現を作成
      const escapedWord = word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      const regex = new RegExp(escapedWord, 'g');
      script = script.replace(regex, reading);
    }
  }

  // 文章の区切り（。）に1秒の無音を挿入
  script = script.replace(/。/g, '。<break time="1000ms"/>');
}

// 5. JSONエスケープ処理
const escapedScript = script
  .replace(/\\/g, "\\\\")
  .replace(/"/g, '\\"')
  .replace(/\n/g, "\\n")
  .replace(/\r/g, "\\r")
  .replace(/\t/g, "\\t");

return {
  ssmlText: `<speak>${escapedScript}</speak>`
};

// 1. スプレッドシートから届いたデータを取得
const fullText = $input.item.json["音声原稿"] || "";
const filename = $input.item.json["Filename"] || "voice";

// 2. 「。」で分割し、空の要素を除去する
// 句点を残すために split(/(?<=。)/) を使うのがコツです
const sentences = fullText.split(/(?<=。)/).filter(s => s.trim() !== "");

// 3. 分割された文章ごとに新しいアイテムを作成
return sentences.map((sentence, index) => {
  return {
    json: {
      // 分割された1文
      "音声原稿": sentence.trim(),
      // 元のファイル名を保持
      "Filename": filename,
      // 何番目の文章か（後の保存用）
      "index": index
    }
  };
});

// 1. 各ノード名を画像に合わせて指定
const BUNKATSU_NODE_NAME = "Code in JavaScript2"; 
const JISHO_NODE_NAME = "Get row(s) in sheet1"; 

// 2. 「2つ前のノード」から分割された原稿の情報を直接取得
// 直前の「辞書」ノードに汚染されていない純粋な分割データを取得します
let sourceNode;
try {
  sourceNode = $node[BUNKATSU_NODE_NAME];
} catch (e) {
  throw new Error(`ノード名「${BUNKATSU_NODE_NAME}」が見つかりません。`);
}

let script = sourceNode.json["音声原稿"] || "";
let filename = sourceNode.json["Filename"] || "voice";
let index = sourceNode.json["index"] || 0;

// 3. 辞書ノードの「すべての行」を取得
let dictionaryItems = [];
try {
  dictionaryItems = $(JISHO_NODE_NAME).all();
} catch (e) {
  // 辞書が取得できない場合は置換せずに進む
}

// 4. 置換処理（scriptをベースに辞書を適用）
if (script !== "" && dictionaryItems.length > 0) {
  for (const item of dictionaryItems) {
    const word = item.json.Word;
    const reading = item.json.Reading;

    if (word && reading) {
      // 特殊文字をエスケープして正規表現を作成
      const regex = new RegExp(word.replace(/[.*+?^${}()|[\]\\]/g, '\\$&'), 'g');
      script = script.replace(regex, reading);
    }
  }
}

// 5. JSONエスケープ処理（改行や引用符によるJSONエラーを防止）
const escapedScript = script.replace(/\\/g, "\\\\").replace(/"/g, '\\"').replace(/\n/g, "\\n");

// 6. 出力（HTTP Requestが必要とする形式にまとめ直す）
// エスケープ処理を一旦リセットし、純粋なタグとして組み立てる
const finalSSML = `<speak><prosody rate="1.0" pitch="0st" volume="0dB">${script}</prosody></speak>`;

return {
  json: {
    "音声原稿": script,
    "Filename": filename,
    "index": index,
    "ssmlText": finalSSML // ここではバックスラッシュを入れない
  }
};
